package com.nekopin.stickers;
import android.content.*;import android.content.res.AssetFileDescriptor;import android.database.*;import android.database.MatrixCursor;import android.net.Uri;import android.os.ParcelFileDescriptor;import java.io.*;import org.json.*;
public class StickerProvider extends ContentProvider {
 static final String ID="nekopin_oc_01";private JSONObject pack;private JSONArray stickers;
 public boolean onCreate(){try{InputStream in=getContext().getAssets().open("contents.json");ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] tmp=new byte[4096];int n;while((n=in.read(tmp))!=-1)b.write(tmp,0,n);pack=new JSONObject(b.toString("UTF-8")).getJSONArray("sticker_packs").getJSONObject(0);stickers=pack.getJSONArray("stickers");return true;}catch(Exception e){return false;}}
 public String getType(Uri u){return "image/webp";}
 public Cursor query(Uri uri,String[] projection,String selection,String[] args,String order){String path=uri.getPath();if(path==null)return null;
 try{if(path.equals("/metadata")||path.equals("/metadata/"+ID)){String[] cols={"sticker_pack_identifier","sticker_pack_name","sticker_pack_publisher","sticker_pack_icon","android_play_store_link","ios_app_store_link","publisher_email","publisher_website","privacy_policy_website","license_agreement_website","image_data_version","avoid_cache","animated_sticker_pack"};MatrixCursor c=new MatrixCursor(cols);c.addRow(new Object[]{ID,"Nekopin Stickers","Nekopin","tray.png","","","","","","","1",0,0});return c;}
 if(path.equals("/stickers/"+ID)){MatrixCursor c=new MatrixCursor(new String[]{"sticker_file_name","sticker_emoji"});for(int i=0;i<stickers.length();i++)c.addRow(new Object[]{stickers.getJSONObject(i).getString("image_file"),"✨"});return c;}
 if(path.equals("/stickers_asset/"+ID)){MatrixCursor c=new MatrixCursor(new String[]{"sticker_file_name"});for(int i=0;i<stickers.length();i++)c.addRow(new Object[]{stickers.getJSONObject(i).getString("image_file")});return c;}
 }catch(Exception e){}return null;}
 public AssetFileDescriptor openAssetFile(Uri uri,String mode)throws FileNotFoundException{String path=uri.getPath();String prefix="/stickers_asset/"+ID+"/";if(path==null||!path.startsWith(prefix))throw new FileNotFoundException();String filename=path.substring(prefix.length());if(filename.contains("/")||filename.contains(".."))throw new FileNotFoundException();try{return getContext().getAssets().openFd("stickers/"+filename);}catch(IOException e){throw new FileNotFoundException(e.toString());}}
 public ParcelFileDescriptor openFile(Uri uri,String mode)throws FileNotFoundException{String path=uri.getPath();String prefix="/stickers_asset/"+ID+"/";if(path==null||!path.startsWith(prefix))throw new FileNotFoundException();String filename=path.substring(prefix.length());if(filename.contains("/")||filename.contains(".."))throw new FileNotFoundException();try{File dir=new File(getContext().getCacheDir(),"stickers");dir.mkdirs();File f=new File(dir,filename);if(!f.exists()){InputStream in=getContext().getAssets().open("stickers/"+filename);FileOutputStream out=new FileOutputStream(f);byte[] buf=new byte[8192];int n;while((n=in.read(buf))>0)out.write(buf,0,n);out.close();in.close();}return ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY);}catch(IOException e){throw new FileNotFoundException(e.toString());}}
 public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){return 0;}public int update(Uri u,ContentValues v,String s,String[] a){return 0;}
}
